function calc(a, op, b) {
  switch (op) {
    case "+": return a + b;
    case "-": return a - b;
    case "*": return a * b;
    case "/":
      if (b === 0) return "除数不能为0";
      return a / b;
    default:
      return "不支持的运算符";
  }
}

